    if ($_SERVER['REQUEST_METHOD']==='POST' && ($_POST['action']??'')==='login') {
        $u=(string)($_POST['user']??''); $p=(string)($_POST['pass']??'');
        if (hash_equals($adminUser,$u) && $adminHash && password_verify($p,$adminHash)) { session_regenerate_id(true); $_SESSION['auth']=true; $_SESSION['csrf']=bin2hex(random_bytes(24)); header('Location: index.php'); exit; }
        $error='Invalid username or password.';
    }
