ntacts where you have a lawful/appropriate basis to send. Unsubscribed contacts are suppressed by campaign queries.</p><table><tr><th>Email</th><th>Source</th><th>Status</th><th>First seen</th><th>Actions</th></tr><?php foreach($contacts as $c):?><tr><td><?=esc($c['email'])?></td><td><?php if($c['source_url']):?><a href="<?=esc($c['source_url'])?>" target="_blank" rel="noopener">source</a><?php endif;?></td><td><?=esc($c['consent_status'])?></td><td><?=esc($c['first_seen_at'])?></td><td><?php if($c['consent_status']==='pending'):?><form class="inline" method="post"><input type="hidden" name="csrf" value="<?=$csrf?>"><input type="hidden" name="action" value="approve"><input type="hidden" name="id" value="<?=$c['id']?>"><button>Approve</button></form> <form class="inline" method="post"><input type="hidden" name="csrf" value="<?=$csrf?>"><input type="hidden" name="action" value="block"><input type="hidden" name="id" value="<?=$c['id']?>"><button>Block</button></form><?php elseif($c['consent_status']==='approved'):?><form class="inline" method="post"><input type="hidden" name="csrf" value="<?=$csrf?>"><input type="hidden" name="action" value="unsubscribe"><input type="hidden" name="id" value="<?=$c['id']?>"><button>Unsubscribe</button></form><?php endif;?></td></tr><?php endforeach;?></table></section><section class="card"><h2>Campaigns</h2><p class="muted">Campaigns are separate by brand. Keep <code>dry_run=true</code> until SMTP and recipient authorization are verified.</p><table><tr><th>ID</th><th>Brand</th><th>Subject</th><th>Enabled</th></tr><?php foreach($campaigns as $c):?><tr><td><?=$c['id']?></td><td><?=esc($c['brand'])?></td><td><?=esc($c['subject'])?></td><td><?=((int)$c['enabled'])?'Yes':'No'?></td></tr><?php endforeach;?></table></section><section class="card"><h2>Operational notes</h2><p>Run <code>cron/run.php</code> from cPanel Cron Jobs every 15–30 minutes. Keep dry-run enabled during testing.</p></section></body></html>
